mapper.select:
SELECT w.*, a.account_no AS accountNo, a.balance AS balance, t.user_name AS tellerName, m.user_name AS managerName FROM large_withdraw_apply w LEFT JOIN account a ON a.account_id=w.account_id LEFT JOIN `user` t ON t.user_id=w.apply_teller_id LEFT JOIN `user` m ON m.user_id=w.approve_manager_id
AND a.user_id = #{userId}
AND w.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND a.account_no LIKE CONCAT('%', #{accountNo}, '%')
AND w.apply_status = #{applyStatus}
ORDER BY w.apply_id ASC
